const envelope = $input.first().json;
const update = envelope.body ?? envelope;
const message = update.channel_post ?? update.message ?? update.edited_channel_post ?? update.edited_message;

if (!message || message.message_id === undefined || message.message_id === null || message.chat?.id === undefined || message.chat?.id === null) {
  throw new Error('Expected a Telegram message/channel_post with chat.id and message_id');
}

const chatId = String(message.chat.id);
const messageId = String(message.message_id);
const channel = message.chat.username ?? message.chat.title ?? null;
const publicUsername = message.chat.username ? String(message.chat.username).replace(/^@/, '') : null;
const privateChatPart = chatId.startsWith('-100') ? chatId.slice(4) : null;
const messageUrl = publicUsername
  ? `https://t.me/${publicUsername}/${messageId}`
  : privateChatPart
    ? `https://t.me/c/${privateChatPart}/${messageId}`
    : null;

function normalizeForwardOrigin(msg) {
  const origin = msg.forward_origin ?? null;
  if (origin) {
    const originChat = origin.chat ?? origin.sender_chat ?? null;
    const originUser = origin.sender_user ?? null;
    return {
      type: origin.type ?? null,
      date: origin.date ?? null,
      chat_id: originChat?.id !== undefined && originChat?.id !== null ? String(originChat.id) : null,
      message_id: origin.message_id !== undefined && origin.message_id !== null ? String(origin.message_id) : null,
      channel: originChat?.username ?? originChat?.title ?? null,
      sender_user_id: originUser?.id !== undefined && originUser?.id !== null ? String(originUser.id) : null,
      author_signature: origin.author_signature ?? null,
      sender_user_name: origin.sender_user_name ?? null
    };
  }

  const legacyChat = msg.forward_from_chat ?? null;
  const legacyUser = msg.forward_from ?? null;
  if (!legacyChat && !legacyUser && !msg.forward_sender_name) {
    return null;
  }
  return {
    type: legacyChat ? 'legacy_chat' : 'legacy_user',
    date: msg.forward_date ?? null,
    chat_id: legacyChat?.id !== undefined && legacyChat?.id !== null ? String(legacyChat.id) : null,
    message_id: msg.forward_from_message_id !== undefined && msg.forward_from_message_id !== null ? String(msg.forward_from_message_id) : null,
    channel: legacyChat?.username ?? legacyChat?.title ?? null,
    sender_user_id: legacyUser?.id !== undefined && legacyUser?.id !== null ? String(legacyUser.id) : null,
    author_signature: msg.forward_signature ?? null,
    sender_user_name: msg.forward_sender_name ?? null
  };
}

const attachments = [];
const addAttachment = (type, media) => {
  if (!media) return;
  attachments.push({
    type,
    file_id: media.file_id ?? null,
    file_unique_id: media.file_unique_id ?? null,
    file_name: media.file_name ?? null,
    mime_type: media.mime_type ?? null,
    file_size: media.file_size ?? null,
    width: media.width ?? null,
    height: media.height ?? null,
    duration: media.duration ?? null,
    media_group_id: message.media_group_id ?? null
  });
};

if (Array.isArray(message.photo) && message.photo.length > 0) {
  addAttachment('photo', message.photo[message.photo.length - 1]);
}
addAttachment('document', message.document);
addAttachment('animation', message.animation);
addAttachment('video', message.video);
addAttachment('audio', message.audio);
addAttachment('voice', message.voice);
addAttachment('video_note', message.video_note);
addAttachment('sticker', message.sticker);

const forwardedFrom = normalizeForwardOrigin(message);
const normalized = {
  event_type: 'telegram_vacancy_post',
  idempotency_key: `telegram:${chatId}:${messageId}`,
  source: {
    chat_id: chatId,
    message_id: messageId,
    channel,
    message_url: messageUrl
  },
  post_text: String(message.text ?? message.caption ?? '').trim(),
  attachments,
  raw: {
    telegram_update: update,
    normalized_forward: forwardedFrom
  }
};

return [{ json: normalized }];
